  return `<section class="teaching-select ${compact?'compact':''}" aria-label="Betreuung"><div class="teaching-select-head">${icon('school')}<strong>${teaching()?'Betreuung':'Workspace'}</strong></div><label class="field"><span>Gruppe</span><select id="teaching-group"><option value="">Mein Workspace</option>${teachingGroups.map(g=>`<option value="${g.id}" ${g.id===teachingGroup?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>${group?`<label class="field"><span>Teilnehmer</span>${group.members.length>12?'<input type="search" id="teaching-search" aria-label="Teilnehmer suchen" placeholder="Name suchen …">':''}<select id="teaching-person" aria-label="Teilnehmer" ${!group.members.length?'disabled':''}>${group.members.map(m=>`<option value="${m.id}" ${m.id===teachingPerson?'selected':''}>${esc(m.name)}${m.role==='teacher'?' · Lehrer':''}</option>`).join('')||'<option>Keine Teilnehmer</option>'}</select></label><p class="teaching-note">${group.members.length?`Sie bearbeiten Projekte und Dateien von <strong>${esc(teachingName())}</strong>.`:'Dieser Gruppe sind noch keine Teilnehmer zugeordnet.'}</p>`:''}</section>`;
