    const choose=$('[data-action="choose-chat-file"]');choose.hidden=!sharing.enabled;$('#chat-file').accept=sharing.types.map(t=>'.'+t).join(',');$('#chat-sharing-hint').textContent=sharing.enabled?'Datei teilen · bis '+bytes(sharing.max_bytes):'Dateien teilen ist deaktiviert.';
