  const clearFile=()=>{selectedFile=null;$('#chat-file').value='';$('#pending-file').hidden=true;};
  $('#chat-group')?.addEventListener('change',async e=>{const previous=chatGroup;if(($('#message').value.trim()||selectedFile)&&!await confirm('Gruppe wechseln','Ihr nicht gesendeter Entwurf wird verworfen.','Wechseln')){e.target.value=previous;return;}chatGroup=e.target.value;generation++;after=0;revision=null;history=[];clearFile();$('#message').value='';$('#chat-items').replaceChildren();$('#chat-older').hidden=true;try{await load();}catch(e){toast(e.message,true);}});
  $('#chat-older').onclick=async e=>{e.target.disabled=true;try{if(history.length)await load(history[0].id);}catch(err){toast(err.message,true);}finally{e.target.disabled=false;}};
  bind('choose-chat-file',()=>$('#chat-file').click());$('#chat-file').onchange=()=>{const f=$('#chat-file').files[0];if(!f)return;if(!sharing.enabled||!sharing.types.includes(f.name.split('.').pop().toLowerCase())||f.size<1||f.size>sharing.max_bytes){clearFile();toast('Bitte einen freigegebenen Dateityp innerhalb der erlaubten Größe auswählen.',true);return;}selectedFile=f;$('#pending-file').hidden=false;$('#pending-file').innerHTML=`<span>${icon('description')}${esc(f.name)} · ${bytes(f.size)}</span>${ib('close','remove-chat-file','Anhang entfernen')}`;bind('remove-chat-file',clearFile);};
